import { useEffect, useState } from 'react';

function Clock({ tickMs }: { tickMs: number }) {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    // runs after mount, and again whenever tickMs changes
    const id = setInterval(() => setNow(new Date()), tickMs);
    // cleanup: before each re-run with a new tickMs, and at unmount
    return () => clearInterval(id);
  }, [tickMs]);

  return <time>{now.toLocaleTimeString()}</time>;
}

export default function App() {
  const [visible, setVisible] = useState(true);
  return (
    <div>
      <button onClick={() => setVisible((v) => !v)}>toggle (unmounts the clock)</button>
      {visible && <Clock tickMs={1000} />}
    </div>
  );
}
