import { memo, useCallback, useMemo, useState } from 'react';

type Item = { id: string; name: string };

const Row = memo(function Row({ item, onPick }: { item: Item; onPick: (id: string) => void }) {
  return <li onClick={() => onPick(item.id)}>{item.name}</li>;
});

export default function App() {
  const [query, setQuery] = useState('');
  const [picked, setPicked] = useState<string | null>(null);
  const items = useMemo<Item[]>(
    () => [{ id: 'a', name: 'Alpha' }, { id: 'b', name: 'Beta' }],
    [],
  );

  // stable reference: rows don't re-render while the user types in the filter
  const onPick = useCallback((id: string) => setPicked(id), []);
  const visible = useMemo(
    () => items.filter((i) => i.name.toLowerCase().includes(query.toLowerCase())),
    [items, query],
  );

  return (
    <div>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>{visible.map((item) => <Row key={item.id} item={item} onPick={onPick} />)}</ul>
      {picked && <p>Picked: {picked}</p>}
    </div>
  );
}
