import { useEffect, useState } from 'react';

// the reusable logic: any component can subscribe to window width
function useWindowWidth(): number {
  const [width, setWidth] = useState(window.innerWidth);
  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);
  return width;
}

function Sidebar() {
  const width = useWindowWidth(); // independent subscription
  if (width < 600) return null;
  return <aside>Wide-screen sidebar</aside>;
}

export default function App() {
  const width = useWindowWidth(); // its own state, same logic
  return (
    <div>
      <p>Window: {width}px</p>
      <Sidebar />
    </div>
  );
}
