import { configureStore, createSlice } from '@reduxjs/toolkit';
import type { PayloadAction } from '@reduxjs/toolkit';

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: [] as string[], total: 0 },
  reducers: {
    // "mutations" are safe here: Immer turns them into immutable updates
    itemAdded(state, action: PayloadAction<{ sku: string; price: number }>) {
      state.items.push(action.payload.sku);
      state.total += action.payload.price;
    },
    cartCleared(state) {
      state.items = [];
      state.total = 0;
    },
  },
});

export const { itemAdded, cartCleared } = cartSlice.actions;

export const store = configureStore({
  reducer: { cart: cartSlice.reducer },
});
export type RootState = ReturnType<typeof store.getState>;

store.dispatch(itemAdded({ sku: 'book-42', price: 25 }));
console.log(store.getState().cart); // { items: ['book-42'], total: 25 }
