import { renderToString } from 'react-dom/server';
import { hydrateRoot } from 'react-dom/client';
import { useState } from 'react';

function App({ initialCount }: { initialCount: number }) {
  const [count, setCount] = useState(initialCount);
  // interactive only after hydration attaches this handler
  return <button onClick={() => setCount((c) => c + 1)}>Count: {count}</button>;
}

// ── server (per request) ─────────────────────────────────
function handleRequest(): string {
  const html = renderToString(<App initialCount={5} />);
  return `<!doctype html>
<html><body>
  <div id="root">${html}</div>
  <script>window.__DATA__ = ${JSON.stringify({ initialCount: 5 })}</script>
  <script type="module" src="/client.js"></script>
</body></html>`;
}

// ── client entry (client.js) ─────────────────────────────
declare global { interface Window { __DATA__: { initialCount: number } } }
hydrateRoot(
  document.getElementById('root')!,
  <App initialCount={window.__DATA__.initialCount} />, // must match the server render
);

void handleRequest;
```

