// build-time prerender script — the essence of what SSG frameworks automate
import { writeFileSync, mkdirSync } from 'node:fs';
import { renderToString } from 'react-dom/server';

type Post = { slug: string; title: string; body: string };

function PostPage({ post }: { post: Post }) {
  return (
    <article>
      <h1>{post.title}</h1>
      <p>{post.body}</p>
    </article>
  );
}

// at build time we can hit the CMS/database freely — visitors never wait for it
const posts: Post[] = [
  { slug: 'hello-ssg', title: 'Hello SSG', body: 'Rendered once, served forever.' },
  { slug: 'why-cdn', title: 'Why CDN', body: 'No server, no cold starts.' },
];

mkdirSync('dist/posts', { recursive: true });
for (const post of posts) {
  const html = renderToString(<PostPage post={post} />);
  writeFileSync(
    `dist/posts/${post.slug}.html`,
    `<!doctype html><html><body><div id="root">${html}</div></body></html>`,
  );
}
// deploy dist/ to any static host — every request is just a file read
